@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open("res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if not n.begins_with("."):
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_walk(p, out)
			else:
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk("", files)
	var removed: Array = []
	var failed: Array = []
	var d := DirAccess.open("res://")
	for f in files:
		var fs := String(f)
		if fs.get_extension() != "import":
			continue
		var txt: String = FileAccess.get_file_as_string("res://" + fs)
		var arr := txt.split("source_file=\"")
		if arr.size() <= 1:
			continue
		var sf: String = arr[1].get_slice("\"", 0)
		var expect: String = "res://" + fs.substr(0, fs.length() - 7)
		var broken := (not FileAccess.file_exists(sf)) or (sf != expect)
		if broken:
			var err := d.remove(fs)
			if err == OK:
				removed.append(fs + " (was -> " + sf + ")")
			else:
				failed.append(fs + " err=" + str(err))
	# also remove the leftover runner marker file
	var extra := []
	if FileAccess.file_exists("res://tools/gc_runner_started.gd"):
		var e2 := d.remove("tools/gc_runner_started.gd")
		extra.append("gc_runner_started.gd removed=" + str(e2 == OK))
	var rep := {"removed_count": removed.size(), "removed": removed, "failed": failed, "extra": extra}
	var out := FileAccess.open("res://tools/gc_fix_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "FIX removed=" + str(removed.size()) + " failed=" + str(failed.size())
